7	public class SeatMapService(AppDbContext dbContext)
8	{
9	    public async Task<SeatMapDto?> GetSeatMapAsync(Guid eventId)
10	    {
11	        var roomId = await dbContext.Events
12	            .Where(e => e.Id == eventId)
13	            .Select(e => (Guid?)e.RoomId)
14	            .FirstOrDefaultAsync();
15	
16	        if (roomId is null)
17	        {
18	            return null;
19	        }
20	
21	        var room = await dbContext.Rooms
22	            .Where(r => r.Id == roomId.Value)
23	            .Select(r => new { r.Reihen, r.SpaltenAnzahl, r.GangSpalten })
24	            .FirstAsync();
25	
26	        var seats = await dbContext.Seats
27	            .Where(s => s.RoomId == roomId.Value)
28	            .OrderBy(s => s.Row)
29	            .ThenBy(s => s.Column)
30	            .Select(s => new SeatDto(s.Id, s.Row, s.Column, SeatStatus.Free))
31	            .ToListAsync();
32	
33	        var priceCategories = await dbContext.PriceCategories
34	            .Where(pc => pc.EventId == eventId)
35	            .OrderBy(pc => pc.Reihenfolge)
36	            .Select(pc => new PriceCategoryDto(pc.Id, pc.Name, pc.Preis))
37	            .ToListAsync();
38	
39	        return new SeatMapDto(eventId, room.Reihen, room.SpaltenAnzahl, room.GangSpalten, seats, priceCategories);
40	    }
41	}
